-- v0.27.2 (team 2026-11-13): FEEDCORN (Sandy Hills Farms) = Corn policy - RMA Coarse Grains Crop Provisions (22-0041) sec. 6(b)(1):
-- corn "planted for harvest either as grain or as silage". FEEDBEAN: no insurance - the soybean policy insures the beans, not forage.
CFAInsurance.FEEDCORN = CFAInsurance.MAIZE
CFAInsurance.SILAGEMAIZE = CFAInsurance.MAIZE   -- v0.29.2 (team 2026-11-15): silage corn = Corn policy, same provision (grain or silage)
-- v1.0.4 (team yes 2026-11-23): corn / soybean / sorghum types on U.S. maps get the plain crop's policy, the same way as FEEDCORN:
-- corn types = Corn policy (grain or silage, 22-0041 sec. 6(b)(1)); grain soybean types = Soybean policy; feed and cattle-feed
-- sorghum = Grain Sorghum policy. CATTLEFEEDBEAN: no U.S. insurance, same as FEEDBEAN (the soybean policy insures the beans, not forage).
CFAInsurance.KTYPES = {NONGMOCORN = "MAIZE", ECOCORN = "MAIZE", BIOCORN = "MAIZE", FOODGRADECORN = "MAIZE", CATTLEFEEDCORN = "MAIZE",
