for k, base in pairs(CFAInsurance.KTYPES) do CFAInsurance[k] = CFAInsurance[base] end

-- v0.28 (team 2026-11-14): POLAND - state-subsidized crop insurance (ustawa z 7 lipca 2005 o ubezpieczeniach upraw rolnych).
-- Source: Ministry of Agriculture (MRiRW) answer to Sejm interpellation 10824 (2025): 2023 and 2024 totals for all crops -
-- sum insured 32,867,945.70 / 32,074,489.62 thousand zl on 3,651,768.55 / 3,812,848.07 ha; premiums 1,013,806.82 / 1,018,834.99
-- thousand zl, of which state subsidy 624,094.48 / 628,171.60. High end of the two years (Rule #1): value 9,000.5 zl/ha (2023),
-- premium 3.176 % of sum insured (2024), farmer pays 38.44 % of it (2023). zl -> US$ by the ECB annual reference rates
-- (2023: 4.54197 PLN and 1.08127 USD per EUR) so the money matches CFA's USDA rows: $2,142.69/ha = $867.12/acre.
-- Policy terms (Rzecznik Finansowy analysis, 2023): a claim needs a 10 % loss; deductible up to 10 % -> paid on the loss above 10 %
-- (coverage 90 %). One rate for all crops (the Ministry gives no crop split). Crops: those the law's insurance covers -
-- cereals, maize, rapeseed, hops, tobacco, field vegetables, fruit, strawberries, potatoes, sugar beet, legumes.
CFAInsurance.PL_ALL = {state = "PL", src = "Poland: Ministry of Agriculture 2023-2024", name = "Poland subsidized crop insurance",
    plans = {{plan = "PL", rows = {{cov = 0.9, liab = 780.40, prem = 27.54, farmer = 10.59}}}}}
CFAInsurance.PL_CROPS = {WHEAT = true, BARLEY = true, OAT = true, RYE = true, TRITICALE = true, BUCKWHEAT = true, MILLET = true,
    MAIZE = true, FEEDCORN = true, SILAGEMAIZE = true, CANOLA = true, TOBACCO = true, POTATO = true, SUGARBEET = true,
    SOYBEAN = true, PEA = true, BLACKBEAN = true, PINTOBEAN = true, GREENBEAN = true, LENTILS = true, CHICKPEAS = true, FEEDBEAN = true,
    CARROT = true, BEETROOT = true, PARSNIP = true, ONION = true, SPINACH = true, GRAPE = true}
CFAInsurance.PLAN_NAMES.PL = "Poland subsidized (10 % deductible)"

-- v0.28 (team 2026-11-14): GERMANY - hail insurance (no state subsidy: the farmer pays it all). Hail damage only.
-- Premium and value: Vereinigte Hagel annual report 2024, German business: premiums 151.1 M EUR on a sum insured of 9.9 bn EUR
-- and 4.8 M ha -> premium 1.526 % of value, value 2,062.5 EUR/ha. EUR -> US$ by the ECB 2024 annual reference rate (1.08238)
-- so the money matches CFA's USDA rows: $903.43/acre, premium $13.79/acre.
-- Terms: Hagelgilde general hail conditions AHagB 2017 - integral franchise 5 % (a hail loss under 5 % is not paid, 5 % or more is
-- paid in full), highest payment 95 % for arable crops, 80 % for fruit, vegetables and potatoes.
CFAInsurance.DE_HAIL = {state = "DE", src = "Germany: Vereinigte Hagel 2024, Hagelgilde AHagB 2017", name = "German hail insurance",
    plans = {{plan = "DEH", rows = {{cov = 1.0, liab = 903.43, prem = 13.79, farmer = 13.79}}}}}
CFAInsurance.DE_HAIL_VEG = {state = "DE", src = "Germany: Vereinigte Hagel 2024, Hagelgilde AHagB 2017", name = "German hail insurance",
