-- v1.0.4: in Poland and Germany the types follow their plain crop (cattle-feed bean like FEEDBEAN)
for k, base in pairs(CFAInsurance.KTYPES) do
    if CFAInsurance.PL_CROPS[base] then CFAInsurance.PL_CROPS[k] = true end
    CFAInsurance.DE_CROPS[k] = CFAInsurance.DE_CROPS[base]
end
CFAInsurance.PL_CROPS.CATTLEFEEDBEAN = CFAInsurance.PL_CROPS.FEEDBEAN
CFAInsurance.DE_CROPS.CATTLEFEEDBEAN = CFAInsurance.DE_CROPS.FEEDBEAN

